@startuml

class Person {
  + personID : int
  + phoneNumber : string
  + researchKeywords : string[]
  + institutionCode : int
}

abstract class ScientificArticle {
  + DOI : string
  + title : string
  + authors : Person[]
  + authorPositions : int[]
}

class PeerReviewedPaper extends ScientificArticle {
  + citationCount : int
  + reviewers : Person[]
}

class TechnicalReport extends ScientificArticle {
  + publisherCode : int
}

class Publisher {
  + name : string
}

class Journal {
  + name : string
  + publisherCode : int
  + impactFactor : float
}

Person "1" -- "0..*" PeerReviewedPaper : author
Person "1" -- "0..*" TechnicalReport : author
PeerReviewedPaper "1" -- "0..*" Person : reviewer
TechnicalReport "1" -- "1" Publisher : publishedBy
Publisher "1" *-- "0..*" Journal : publishes

@enduml

